'use client';
const require_select = require("./select.cjs");
const require_select_optgroup = require("./select-optgroup.cjs");
const require_select_option = require("./select-option.cjs");
//#region src/components/select/index.ts
/**
* Select component, used to display a native select.
*
* @example
* <Select>
*   <Select.Option value='1'>Option 1</Select.Option>
*   <Select.Option value='2'>Option 2</Select.Option>
* </Select>
*/
const SelectComponent = Object.assign(require_select.Select, {
	Option: require_select_option.SelectOption,
	Optgroup: require_select_optgroup.SelectOptgroup
});
SelectComponent.Option.displayName = "Select.Option";
SelectComponent.Optgroup.displayName = "Select.Optgroup";
//#endregion
exports.Select = SelectComponent;
exports.SelectOptgroup = require_select_optgroup.SelectOptgroup;
exports.SelectOption = require_select_option.SelectOption;
